Running command: python3 -c "
data = b' ' * 32765 + b\"'''\"
assert len(data) == 32768
open('/tmp/poc2', 'wb').write(data)
print('written', len(data))
"
# Test with the standalone lexer
cat > /tmp/test_lex3.c <<'EOF'
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
static unsigned char static_data[32768];
struct lexer {
    const char *start, *pos, *end;
};
static int next(struct lexer *lexer)
{
    if (lexer->pos >= lexer->end) {
        lexer->pos = lexer->end + 1;
        return '\0';
    }
    int r = *lexer->pos;
    lexer->pos++;
    return r;
}
static void ignore(struct lexer *lexer) { lexer->start = lexer->pos; }
static void advance_n(struct lexer *lexer, size_t n) { lexer->pos += n; ignore(lexer); }
static int peek(struct lexer *lexer) { int c = next(lexer); lexer->pos--; return c; }
int main(void) {
    size_t size = 32768;
    FILE *f = fopen("/tmp/poc2", "rb");
    fread(static_data, 1, size, f);
    fclose(f);
    struct lexer lexer = {
        .start = (char*)static_data,
        .pos = (char*)static_data,
        .end = (char*)static_data + size - 1,
    };
    // simulate lex_config: skip spaces then hit '''
    int chr;
    while (1) {
        chr = next(&lexer);
        if (chr == '\0') break;
        if (chr == ' ') { ignore(&lexer); continue; }
        if (chr == '\'' && !strncmp(lexer.pos, "''", 2)) {
            printf("multiline at pos=%ld\n", (long)(lexer.pos - (char*)static_data));
            break;
        }
        break;
    }
    int p = peek(&lexer);
    char *end = (p == '"') ? "\"\"\"" : "'''";
    advance_n(&lexer, strlen("'''") - 1);
    printf("after advance pos=%ld\n", (long)(lexer.pos - (char*)static_data));
    int r = strncmp(lexer.pos, end, 3);
    printf("strncmp result=%d\n", r);
    return 0;
}
EOF
gcc -fsanitize=address -g -o /tmp/test_lex3 /tmp/test_lex3.c && /tmp/test_lex3; echo "exit: $?"

